Your expense tracker is below: add an item, pick a category, set a monthly budget and see totals by category. It keeps entries only while this chat is open, so nothing is saved after you close it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:12px;background:#fafaf7;color:#222}
h2{margin:0 0 8px;font-size:18px}
.row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{padding:7px;border:1px solid #bbb;border-radius:6px;font-size:14px}
input{flex:1;min-width:90px}
button{background:#2e7d5b;color:#fff;border-color:#2e7d5b;cursor:pointer}
button.x{background:none;color:#b00;border:none;padding:2px 6px}
.card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:10px;margin-bottom:10px}
.big{font-size:22px;font-weight:600}
.bar{height:8px;background:#e5e5e0;border-radius:4px;overflow:hidden;margin:2px 0 8px}
.bar i{display:block;height:100%;background:#2e7d5b}
.over{color:#b00}
.item{display:flex;justify-content:space-between;align-items:center;padding:4px 0;border-bottom:1px solid #eee;font-size:14px}
small{color:#666}
</style></head><body>
<h2>Expenses, Nov 2026</h2>
<div class="card">
  <div class="row">
    <input id="d" placeholder="What did you spend on?">
    <input id="a" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="c">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button id="add">Add</button>
  </div>
</div>
<div class="card">
  <div class="row" style="margin:0">
    <input id="b" type="number" min="0" placeholder="Monthly budget (₹)">
  </div>
  <div class="big" id="tot">₹0</div>
  <small id="left">Set a budget to see what is left.</small>
</div>
<div class="card"><b>By category</b><div id="cats"><small>Nothing yet.</small></div></div>
<div class="card"><b>Entries</b><div id="list"><small>Nothing yet.</small></div></div>
<script>
var items=[];
function fmt(n){return '₹'+Math.round(n).toLocaleString('en-IN')}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function draw(){
  var t=0,by={};
  items.forEach(function(i){t+=i.a;by[i.c]=(by[i.c]||0)+i.a});
  document.getElementById('tot').textContent=fmt(t);
  var b=parseFloat(document.getElementById('b').value)||0,l=document.getElementById('left');
  if(b>0){var r=b-t;l.innerHTML=r>=0?fmt(r)+' left of '+fmt(b):'<span class="over">Over budget by '+fmt(-r)+'</span>'}
  else l.textContent='Set a budget to see what is left.';
  var h='';
  Object.keys(by).sort(function(x,y){return by[y]-by[x]}).forEach(function(k){
    h+='<div style="display:flex;justify-content:space-between"><span>'+esc(k)+'</span><span>'+fmt(by[k])+'</span></div><div class="bar"><i style="width:'+(by[k]/t*100)+'%"></i></div>';
  });
  document.getElementById('cats').innerHTML=h||'<small>Nothing yet.</small>';
  var s='';
  items.slice().reverse().forEach(function(i){
    s+='<div class="item"><span>'+esc(i.d)+' <small>'+esc(i.c)+'</small></span><span>'+fmt(i.a)+' <button class="x" data-id="'+i.id+'">✕</button></span></div>';
  });
  document.getElementById('list').innerHTML=s||'<small>Nothing yet.</small>';
}
var n=0;
document.getElementById('add').onclick=function(){
  var d=document.getElementById('d'),a=document.getElementById('a');
  var v=parseFloat(a.value);
  if(!(v>0))return;
  items.push({id:++n,d:d.value.trim()||'Expense',a:v,c:document.getElementById('c').value});
  d.value='';a.value='';draw();
};
document.getElementById('b').oninput=draw;
document.getElementById('list').onclick=function(e){
  var id=e.target.getAttribute('data-id');
  if(id){items=items.filter(function(i){return i.id!=id});draw()}
};
</script>
</body></html>
```

